def evaluate(expr: str) -> float:
    """
    Evaluate an arithmetic expression containing non‑negative numbers (integers or decimals),
    the operators +, -, *, /, parentheses, spaces, and unary minus.
    Normal operator precedence is respected: parentheses > unary minus > * / > + -.
    """
    class Parser:
        __slots__ = ('s', 'i', 'n')

        def __init__(self, s: str):
            self.s = s
            self.i = 0
            self.n = len(s)

        def _skip_spaces(self) -> None:
            while self.i < self.n and self.s[self.i].isspace():
                self.i += 1

        def _peek(self) -> str | None:
            self._skip_spaces()
            return self.s[self.i] if self.i < self.n else None

        def _consume(self) -> str | None:
            self._skip_spaces()
            if self.i < self.n:
                ch = self.s[self.i]
                self.i += 1
                return ch
            return None

        def _parse_number(self) -> float:
            self._skip_spaces()
            start = self.i
            has_digits = False

            # digits before decimal point
            while self.i < self.n and self.s[self.i].isdigit():
                self.i += 1
                has_digits = True

            # decimal point and digits after
            if self.i < self.n and self.s[self.i] == '.':
                self.i += 1
                while self.i < self.n and self.s[self.i].isdigit():
                    self.i += 1
                    has_digits = True

            if not has_digits:
                raise ValueError(f"Invalid number at position {start}")

            return float(self.s[start:self.i])

        def _parse_primary(self) -> float:
            ch = self._peek()
            if ch == '(':
                self._consume()                     # '('
                val = self._parse_expression()
                if self._peek() != ')':
                    raise ValueError("Missing closing parenthesis")
                self._consume()                     # ')'
                return val
            return self._parse_number()

        def _parse_factor(self) -> float:
            ch = self._peek()
            if ch in ('+', '-'):
                op = self._consume()
                val = self._parse_factor()
                return -val if op == '-' else val
            return self._parse_primary()

        def _parse_term(self) -> float:
            val = self._parse_factor()
            while True:
                ch = self._peek()
                if ch == '*':
                    self._consume()
                    val *= self._parse_factor()
                elif ch == '/':
                    self._consume()
                    val /= self._parse_factor()
                else:
                    break
            return val

        def _parse_expression(self) -> float:
            val = self._parse_term()
            while True:
                ch = self._peek()
                if ch == '+':
                    self._consume()
                    val += self._parse_term()
                elif ch == '-':
                    self._consume()
                    val -= self._parse_term()
                else:
                    break
            return val

        def parse(self) -> float:
            result = self._parse_expression()
            self._skip_spaces()
            if self.i != self.n:
                raise ValueError("Unexpected characters at end of expression")
            return result

    return Parser(expr).parse()
